CREATE OR REPLACE FUNCTION hdg_load.contract_version() RETURNS integer
LANGUAGE sql IMMUTABLE AS 'SELECT 2';
CREATE OR REPLACE FUNCTION hdg_load.publish_full_load(p_run_id varchar)
RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $publish$
DECLARE state hdg_load.control%ROWTYPE; run_status text;
    expected_count bigint; actual_count bigint; expected_digest text; copied boolean:=false;
BEGIN
    -- BƯỚC 1: Khóa control và chặn publish khi CDC đang giữ trách nhiệm cập nhật.
    PERFORM pg_advisory_xact_lock(784027,2);
    SELECT * INTO STRICT state FROM hdg_load.control WHERE id=1 FOR UPDATE;
    IF state.cdc_enabled THEN RAISE EXCEPTION 'CDC enabled; separately verified handoff required'; END IF;
    SELECT status INTO STRICT run_status FROM hdg_load.runs WHERE run_id=p_run_id FOR UPDATE;
    IF run_status<>'VALIDATED' THEN RAISE EXCEPTION 'Run must be VALIDATED'; END IF;
    IF (SELECT count(*) FROM hdg_load.table_runs WHERE run_id=p_run_id AND content_equal AND source_rows=stage_rows)<>4 THEN
        RAISE EXCEPTION 'Four validated table audits required';
    END IF;
    LOCK TABLE public.mirror_hdg_nhankhau IN ACCESS EXCLUSIVE MODE;
    LOCK TABLE public.mirror_dm_dantoc IN ACCESS EXCLUSIVE MODE;
    LOCK TABLE public.mirror_dm_quoc_tich IN ACCESS EXCLUSIVE MODE;
    LOCK TABLE public.mirror_dm_dbhc IN ACCESS EXCLUSIVE MODE;
    LOCK TABLE hdg_stage.mirror_hdg_nhankhau IN SHARE MODE;
    LOCK TABLE hdg_stage.mirror_dm_dantoc IN SHARE MODE;
    LOCK TABLE hdg_stage.mirror_dm_quoc_tich IN SHARE MODE;
    LOCK TABLE hdg_stage.mirror_dm_dbhc IN SHARE MODE;
    PERFORM hdg_load.assert_mirror_schema();

    SELECT source_rows,stage_digest INTO STRICT expected_count,expected_digest
       FROM hdg_load.table_runs WHERE run_id=p_run_id AND source_table='VSS_HO_GD_NHANKHAU' AND content_equal;
    SELECT count(*) INTO actual_count FROM hdg_stage.mirror_hdg_nhankhau WHERE load_run_id=p_run_id;
    IF actual_count<>expected_count OR expected_digest IS NULL OR
       expected_digest IS DISTINCT FROM hdg_load.stage_digest('mirror_hdg_nhankhau',p_run_id) THEN
        RAISE EXCEPTION 'Stage count/content audit missing or changed for VSS_HO_GD_NHANKHAU; revalidate against Oracle snapshot';
    END IF;
    PERFORM hdg_load.checked_text(ma_cd, 30, true), hdg_load.checked_text(ma_cn, 30, true), hdg_load.checked_text(ma_ho_gd, 30, true), hdg_load.checked_text(ho_ten, 250, true), hdg_load.checked_text(ho_ten_khac, 250, true), hdg_load.checked_text(gioi_tinh, 1, true), hdg_load.checked_numeric(ngay_sinh, NULL, NULL), hdg_load.checked_text(noi_sinh, 250, true), hdg_load.checked_numeric(ngay_ks, NULL, NULL), hdg_load.checked_text(so_giay_ks, 50, true), hdg_load.checked_text(noi_ks, 250, true), hdg_load.checked_text(qh_chu_ho, 2, true), hdg_load.checked_text(so_cmtnd, 50, true), hdg_load.checked_numeric(ngay_cap_cmtnd, NULL, NULL), hdg_load.checked_text(noi_cap_cmtnd, 250, true), hdg_load.checked_text(so_hc, 50, true), hdg_load.checked_numeric(ngay_cap_hc, NULL, NULL), hdg_load.checked_text(noi_cap_hc, 250, true), hdg_load.checked_text(dia_chi, 500, true), hdg_load.checked_text(dc_lien_lac, 250, true), hdg_load.checked_text(email_acc, 50, true), hdg_load.checked_text(phone_number, 50, true), hdg_load.checked_text(ma_tinh, 10, true), hdg_load.checked_text(ma_huyen, 10, true), hdg_load.checked_text(ma_xa, 10, true), hdg_load.checked_text(nghe_nghiep, 250, true), hdg_load.checked_text(quoc_tich, 10, true), hdg_load.checked_text(is_alive, 1, true), hdg_load.checked_numeric(dead_date, NULL, NULL), hdg_load.checked_text(is_bh, 1, true), hdg_load.checked_text(loai_bh, 30, true), hdg_load.checked_text(ma_bh, 30, true), hdg_load.checked_timestamp(created_date, 0), hdg_load.checked_timestamp(modify_date, 0), hdg_load.checked_text(ma_nv, 100, false), hdg_load.checked_text(ghi_chu, 500, true), hdg_load.checked_text(ma_the, 2000, true), hdg_load.checked_text(ma_so, 2000, true), hdg_load.checked_text(issynch, 1, true), hdg_load.checked_numeric(ngay_batdau, NULL, NULL), hdg_load.checked_numeric(ngay_hethan, NULL, NULL), hdg_load.checked_text(ma_thon, 10, true), hdg_load.checked_text(ischu_ho, 1, true), hdg_load.checked_text(ten_doituong_bh, 2000, true), hdg_load.checked_text(ten_tinh, 250, true), hdg_load.checked_text(ten_huyen, 250, true), hdg_load.checked_text(ten_xa, 250, true), hdg_load.checked_text(ten_thon, 250, true), hdg_load.checked_text(ten_qh_chuho, 250, true), hdg_load.checked_text(ma_doituong_bh, 10, true), hdg_load.checked_text(status, 1, true), hdg_load.checked_text(card_id, 2000, true), hdg_load.checked_text(typeid, 2, true), hdg_load.checked_numeric(ngay_phatsinh, NULL, NULL), hdg_load.checked_text(nguoi_ke_khai, 200, true), hdg_load.checked_text(tran_status, 5, true), hdg_load.checked_text(trang_thai, 1, true), hdg_load.checked_text(ma_tinh_ks, 5, true), hdg_load.checked_text(ma_huyen_ks, 5, true), hdg_load.checked_text(ma_xa_ks, 5, true), hdg_load.checked_text(ten_tinh_ks, 200, true), hdg_load.checked_text(ten_huyen_ks, 200, true), hdg_load.checked_text(ten_xa_ks, 200, true), hdg_load.checked_text(id, 40, true), hdg_load.checked_text(ma_offline, 100, false), hdg_load.checked_numeric(ngay_sinh_bk, NULL, NULL), hdg_load.checked_text(ma_huyen_import, 20, true), hdg_load.checked_text(id_ca, 20, true), hdg_load.checked_text(ngoai_tinh, 10, true), hdg_load.checked_text(ma_nv_tao, 100, false), hdg_load.checked_text(ma_tinh_the, 10, true), hdg_load.checked_text(user_ngoai_tinh, 30, false), hdg_load.checked_text(ma_the_moi, 50, false), hdg_load.checked_text(card_id_moi, 50, true), hdg_load.checked_numeric(sync_tst, 1, 0), hdg_load.checked_text(ma_cd_old, 30, true), hdg_load.checked_text(ho_ten_unsigned, 250, true), hdg_load.checked_numeric(user_id, 10, 0), hdg_load.checked_numeric(user_id_tinh, 10, 0), hdg_load.checked_numeric(user_id_tw, 10, 0), hdg_load.checked_numeric(trang_thai_duyet, 2, 0), hdg_load.checked_numeric(type_pm, 1, 0), hdg_load.checked_numeric(user_update, 10, 0), hdg_load.checked_text(ly_do_phe_duyet, 1000, false), hdg_load.checked_timestamp(approved_date, 0), hdg_load.checked_text(ten_cha_me, 250, true), hdg_load.checked_text(key_sl, 250, false), hdg_load.checked_numeric(dm_dan_toc_id, 19, 0), hdg_load.checked_timestamp(ngay_tao_hc, 0), hdg_load.checked_numeric(user_hc_id, 10, 0), hdg_load.checked_text(user_hc, 100, true), hdg_load.checked_numeric(user_duyet_hc_id, 10, 0), hdg_load.checked_text(user_duyet_hc, 100, true), hdg_load.checked_timestamp(ngay_duyet_hc, 0), hdg_load.checked_text(ly_do_hc, 1000, true), hdg_load.checked_text(user_dms, 100, false), hdg_load.checked_numeric(user_dms_id, 19, 0), hdg_load.checked_timestamp(ngay_de_nghi_dms, 0), hdg_load.checked_numeric(user_duyet_dms_id, 19, 0), hdg_load.checked_text(user_duyet_dms, 100, false), hdg_load.checked_timestamp(ngay_duyet_dms, 0), hdg_load.checked_text(ly_do_dms, 1000, false), hdg_load.checked_numeric(lock_data, NULL, NULL), hdg_load.checked_text(ma_tinh_lh, 10, true), hdg_load.checked_text(ma_huyen_lh, 10, true), hdg_load.checked_text(ma_xa_lh, 10, true), hdg_load.checked_numeric(xac_thuc_bca, 2, 0), hdg_load.checked_text(dang_tg, 20, true), hdg_load.checked_text(so_cccd, 50, true), hdg_load.checked_numeric(trang_thai_quet, 2, 0), hdg_load.checked_numeric(trang_thai_xac_thuc_bca, 2, 0) FROM hdg_stage.mirror_hdg_nhankhau WHERE load_run_id=p_run_id;

    SELECT source_rows,stage_digest INTO STRICT expected_count,expected_digest
       FROM hdg_load.table_runs WHERE run_id=p_run_id AND source_table='VSS_DM_DANTOC' AND content_equal;
    SELECT count(*) INTO actual_count FROM hdg_stage.mirror_dm_dantoc WHERE load_run_id=p_run_id;
    IF actual_count<>expected_count OR expected_digest IS NULL OR
       expected_digest IS DISTINCT FROM hdg_load.stage_digest('mirror_dm_dantoc',p_run_id) THEN
        RAISE EXCEPTION 'Stage count/content audit missing or changed for VSS_DM_DANTOC; revalidate against Oracle snapshot';
    END IF;
    PERFORM hdg_load.checked_numeric(id, 19, 0), hdg_load.checked_text(can_cu, 255, false), hdg_load.checked_text(ma, 2, false), hdg_load.checked_timestamp(ngay_hl, 0), hdg_load.checked_timestamp(ngay_het_hl, 0), hdg_load.checked_text(ten, 100, false) FROM hdg_stage.mirror_dm_dantoc WHERE load_run_id=p_run_id;

    SELECT source_rows,stage_digest INTO STRICT expected_count,expected_digest
       FROM hdg_load.table_runs WHERE run_id=p_run_id AND source_table='VSS_DM_QUOC_TICH' AND content_equal;
    SELECT count(*) INTO actual_count FROM hdg_stage.mirror_dm_quoc_tich WHERE load_run_id=p_run_id;
    IF actual_count<>expected_count OR expected_digest IS NULL OR
       expected_digest IS DISTINCT FROM hdg_load.stage_digest('mirror_dm_quoc_tich',p_run_id) THEN
        RAISE EXCEPTION 'Stage count/content audit missing or changed for VSS_DM_QUOC_TICH; revalidate against Oracle snapshot';
    END IF;
    PERFORM hdg_load.checked_numeric(id, 19, 0), hdg_load.checked_text(ma, 2, false), hdg_load.checked_text(ten, 100, false) FROM hdg_stage.mirror_dm_quoc_tich WHERE load_run_id=p_run_id;

    SELECT source_rows,stage_digest INTO STRICT expected_count,expected_digest
       FROM hdg_load.table_runs WHERE run_id=p_run_id AND source_table='VSS_DM_DBHC' AND content_equal;
    SELECT count(*) INTO actual_count FROM hdg_stage.mirror_dm_dbhc WHERE load_run_id=p_run_id;
    IF actual_count<>expected_count OR expected_digest IS NULL OR
       expected_digest IS DISTINCT FROM hdg_load.stage_digest('mirror_dm_dbhc',p_run_id) THEN
        RAISE EXCEPTION 'Stage count/content audit missing or changed for VSS_DM_DBHC; revalidate against Oracle snapshot';
    END IF;
    PERFORM hdg_load.checked_text(ma_dbhc, 5, true), hdg_load.checked_text(ma_cha, 5, true), hdg_load.checked_text(ten, 200, true), hdg_load.checked_text(tinh_trang, 1, true), hdg_load.checked_text(status, 1, true), hdg_load.checked_timestamp(created_date, 0), hdg_load.checked_numeric(id, 20, 0), hdg_load.checked_text(ma_dbhc_sn, 200, true), hdg_load.checked_numeric(is_lt, 1, 0), hdg_load.checked_numeric(is_cap_xa, NULL, NULL), hdg_load.checked_timestamp(ngay_hieu_luc, 6), hdg_load.checked_timestamp(ngay_het_hieu_luc, 6) FROM hdg_stage.mirror_dm_dbhc WHERE load_run_id=p_run_id;
    -- BƯỚC 2: Sau kiểm schema/digest, chỉ nạp bootstrap vào cả bốn Mirror rỗng.
